 11→pub fn parse_solana_transaction(tx: &Transaction) -> anyhow::Result<Vec<LedgerEntry>> {
 12→    let mut entries = Vec::new();
 13→    let mut entry_index: u32 = 0;
 14→
 15→    let sol_tx: EncodedConfirmedTransactionWithStatusMeta =
 16→        serde_json::from_value(tx.raw_metadata.clone())?;
 17→
 18→    let meta = match &sol_tx.transaction.meta {
 19→        Some(m) => m,
 20→        None => return Ok(vec![]),
 21→    };
 22→
 23→    // Skip failed transactions
 24→    if meta.err.is_some() {
 25→        return Ok(vec![]);
 26→    }
 27→
 28→    let transaction = &sol_tx.transaction.transaction;
 29→    if let solana_transaction_status::EncodedTransaction::Json(ui_tx) = transaction {
 30→        if let solana_transaction_status::UiMessage::Parsed(message) = &ui_tx.message {
 31→            if let Some(idx) = message
 32→                .account_keys
 33→                .iter()
 34→                .position(|k| k.pubkey == tx.wallet_address)
 35→            {
 36→                let lamport_change = extract_sol_change_lamports(meta, idx);
 37→                let fee_lamports = meta.fee;
 38→                let is_fee_payer = idx == 0;
 39→
 40→                // If this wallet is the fee payer, separate fee from the net transfer
 41→                if is_fee_payer && fee_lamports > 0 {
 42→                    // Fee entry (always negative)
 43→                    let fee_amount = lamports_to_sol(-(fee_lamports as i128));
 44→                    entries.push(LedgerEntry {
 45→                        id: deterministic_id(tx.id, entry_index),
 46→                        transaction_id: tx.id,
 47→                        user_id: tx.user_id,
 48→                        wallet_address: tx.wallet_address.clone(),
 49→                        asset_symbol: "SOL".to_string(),
 50→                        amount: fee_amount,
 51→                        entry_type: EntryType::Fee,
 52→                        fiat_value: None,
 53→                    });
 54→                    entry_index += 1;
 55→
 56→                    // Net transfer amount = total balance change + fee (since fee is included in the balance change)
 57→                    let transfer_lamports = lamport_change + fee_lamports as i128;
 58→                    if transfer_lamports != 0 {
 59→                        let transfer_amount = lamports_to_sol(transfer_lamports);
 60→                        entries.push(LedgerEntry {
 61→                            id: deterministic_id(tx.id, entry_index),
 62→                            transaction_id: tx.id,
 63→                            user_id: tx.user_id,
 64→                            wallet_address: tx.wallet_address.clone(),
 65→                            asset_symbol: "SOL".to_string(),
 66→                            amount: transfer_amount,
 67→                            entry_type: EntryType::Transfer,
 68→                            fiat_value: None,
 69→                        });
 70→                        entry_index += 1;
 71→                    }
 72→                } else if lamport_change != 0 {
 73→                    // Non-fee-payer: entire balance change is a transfer
 74→                    let amount = lamports_to_sol(lamport_change);
 75→                    entries.push(LedgerEntry {
 76→                        id: deterministic_id(tx.id, entry_index),
 77→                        transaction_id: tx.id,
 78→                        user_id: tx.user_id,
 79→                        wallet_address: tx.wallet_address.clone(),
 80→                        asset_symbol: "SOL".to_string(),
 81→                        amount,
 82→                        entry_type: EntryType::Transfer,
 83→                        fiat_value: None,
 84→                    });
 85→                    entry_index += 1;
 86→                }
 87→            }
 88→        }
 89→    }
 90→
 91→    // Extract SPL Token Changes
 92→    if let OptionSerializer::Some(pre_token_balances) = &meta.pre_token_balances {
 93→        if let OptionSerializer::Some(post_token_balances) = &meta.post_token_balances {
 94→            for post in post_token_balances {
 95→                let owner_match = match &post.owner {
 96→                    OptionSerializer::Some(owner) => owner == &tx.wallet_address,
 97→                    OptionSerializer::None => false,
 98→                    OptionSerializer::Skip => false,
 99→                };
100→
101→                if owner_match {
102→                    let mint = post.mint.clone();
103→                    let decimals = post.ui_token_amount.decimals as u32;
104→
105→                    let pre_raw = pre_token_balances
106→                        .iter()
107→                        .find(|p| p.account_index == post.account_index)
108→                        .and_then(|p| p.ui_token_amount.amount.parse::<i128>().ok())
109→                        .unwrap_or(0);
110→
111→                    let post_raw = post.ui_token_amount.amount.parse::<i128>().unwrap_or(0);
112→                    let delta_raw = post_raw - pre_raw;
113→
114→                    if delta_raw != 0 {
115→                        let amount = token_raw_to_decimal(delta_raw, decimals);
116→                        let symbol = spl_token_symbol(&mint);
117→                        entries.push(LedgerEntry {
118→                            id: deterministic_id(tx.id, entry_index),
119→                            transaction_id: tx.id,
120→                            user_id: tx.user_id,
121→                            wallet_address: tx.wallet_address.clone(),
122→                            asset_symbol: symbol,
123→                            amount,
124→                            entry_type: EntryType::Transfer,
125→                            fiat_value: None,
126→                        });
127→                        entry_index += 1;
128→                    }
129→                }
130→            }
131→        }
132→    }
133→
134→    let _ = entry_index;
135→    Ok(entries)
136→}
