138→/// Extract the raw lamport balance change for a given account index.
139→/// Uses i128 to avoid truncation when u64 values exceed i64::MAX.
140→fn extract_sol_change_lamports(meta: &UiTransactionStatusMeta, wallet_index: usize) -> i128 {
141→    let pre = meta.pre_balances.get(wallet_index).copied().unwrap_or(0) as i128;
142→    let post = meta.post_balances.get(wallet_index).copied().unwrap_or(0) as i128;
143→    post - pre
144→}
145→
146→/// Convert lamports (i128) to SOL as BigDecimal without floating-point precision loss.
147→fn lamports_to_sol(lamports: i128) -> BigDecimal {
148→    let raw = BigDecimal::from_str(&format!("{}", lamports)).unwrap();
149→    let divisor = BigDecimal::from_str("1000000000").unwrap();
150→    raw / divisor
151→}
152→
153→/// Convert raw token amount to BigDecimal using the token's decimals.
154→fn token_raw_to_decimal(raw: i128, decimals: u32) -> BigDecimal {
155→    let raw_bd = BigDecimal::from_str(&format!("{}", raw)).unwrap();
156→    let divisor = BigDecimal::from_str(&format!("1{}", "0".repeat(decimals as usize))).unwrap();
157→    raw_bd / divisor
158→}
