160→/// Lookup a human-readable symbol for well-known SPL tokens.
161→/// Falls back to the mint address for unknown tokens.
162→fn spl_token_symbol(mint: &str) -> String {
163→    match mint {
164→        "REDACTED" => "USDC".to_string(),
165→        "REDACTED" => "USDT".to_string(),
166→        "So11111111111111111111111111111111111111112" => "SOL".to_string(),
167→        "REDACTED" => "mSOL".to_string(),
168→        "REDACTED" => "WETH".to_string(),
169→        "REDACTED" => "BONK".to_string(),
170→        "REDACTED" => "JUP".to_string(),
171→        "REDACTED" => "stSOL".to_string(),
172→        "REDACTED" => "RLSOL".to_string(),
173→        "REDACTED" => "jitoSOL".to_string(),
174→        _ => mint.to_string(),
175→    }
176→}
