189→/// Extract SPL token transfers from a Solana raw transaction.
190→///
191→/// Uses pre/post token balance arrays from the transaction metadata to compute
192→/// deltas for each token account owner. Emits one `TokenTransfer` per non-zero
193→/// delta, with the owner as either from_address or to_address depending on sign.
194→pub fn extract_solana_token_transfers(
195→    raw_tx_id: Option<Uuid>,
196→    network: &str,
197→    raw_metadata: &serde_json::Value,
198→) -> Vec<TokenTransfer> {
199→    let sol_tx: EncodedConfirmedTransactionWithStatusMeta =
200→        match serde_json::from_value(raw_metadata.clone()) {
201→            Ok(tx) => tx,
202→            Err(_) => return vec![],
203→        };
204→
205→    let meta = match &sol_tx.transaction.meta {
206→        Some(m) => m,
207→        None => return vec![],
208→    };
209→
210→    if meta.err.is_some() {
211→        return vec![];
212→    }
213→
214→    let mut transfers = Vec::new();
215→
216→    if let OptionSerializer::Some(pre_token_balances) = &meta.pre_token_balances {
217→        if let OptionSerializer::Some(post_token_balances) = &meta.post_token_balances {
218→            for post in post_token_balances {
219→                let owner = match &post.owner {
220→                    OptionSerializer::Some(o) => o.clone(),
221→                    _ => continue,
222→                };
223→
224→                let mint = post.mint.clone();
225→                let decimals = post.ui_token_amount.decimals as u32;
226→
227→                let pre_raw = pre_token_balances
228→                    .iter()
229→                    .find(|p| p.account_index == post.account_index)
230→                    .and_then(|p| p.ui_token_amount.amount.parse::<i128>().ok())
231→                    .unwrap_or(0);
232→
233→                let post_raw = post.ui_token_amount.amount.parse::<i128>().unwrap_or(0);
234→                let delta_raw = post_raw - pre_raw;
235→
236→                if delta_raw == 0 {
237→                    continue;
238→                }
239→
240→                let amount = token_raw_to_decimal(delta_raw.unsigned_abs() as i128, decimals);
241→                let symbol = spl_token_symbol(&mint);
242→
243→                let (from, to) = if delta_raw > 0 {
244→                    // Incoming: unknown sender -> owner
245→                    ("unknown".to_string(), owner)
246→                } else {
247→                    // Outgoing: owner -> unknown receiver
248→                    (owner, "unknown".to_string())
249→                };
250→
251→                transfers.push(TokenTransfer {
252→                    id: Uuid::new_v4(),
253→                    raw_transaction_id: raw_tx_id,
254→                    network: network.to_string(),
255→                    token_address: mint,
256→                    token_symbol: Some(symbol),
257→                    from_address: from,
258→                    to_address: to,
259→                    amount,
260→                    decimals: decimals as i32,
261→                    dataset_version_id: None,
262→                    created_at: Utc::now(),
263→                });
264→            }
265→        }
266→    }
267→
268→    transfers
269→}
