275→/// Extract SOL native balance deltas from a Solana raw transaction.
276→///
277→/// Uses pre/post balance arrays and the account keys from the transaction.
278→/// Flags the first signer (index 0) as the fee payer.
279→pub fn extract_solana_native_balance_deltas(
280→    raw_tx_id: Option<Uuid>,
281→    network: &str,
282→    raw_metadata: &serde_json::Value,
283→) -> Vec<NativeBalanceDelta> {
284→    let sol_tx: EncodedConfirmedTransactionWithStatusMeta =
285→        match serde_json::from_value(raw_metadata.clone()) {
286→            Ok(tx) => tx,
287→            Err(_) => return vec![],
288→        };
289→
290→    let meta = match &sol_tx.transaction.meta {
291→        Some(m) => m,
292→        None => return vec![],
293→    };
294→
295→    if meta.err.is_some() {
296→        return vec![];
297→    }
298→
299→    let account_keys: Vec<String> =
300→        if let solana_transaction_status::EncodedTransaction::Json(ui_tx) =
301→            &sol_tx.transaction.transaction
302→        {
303→            match &ui_tx.message {
304→                solana_transaction_status::UiMessage::Parsed(msg) => {
305→                    msg.account_keys.iter().map(|k| k.pubkey.clone()).collect()
306→                }
307→                solana_transaction_status::UiMessage::Raw(msg) => msg.account_keys.clone(),
308→            }
309→        } else {
310→            return vec![];
311→        };
312→
313→    let mut deltas = Vec::new();
314→
315→    for (idx, account) in account_keys.iter().enumerate() {
316→        let pre = meta.pre_balances.get(idx).copied().unwrap_or(0) as i128;
317→        let post = meta.post_balances.get(idx).copied().unwrap_or(0) as i128;
318→        let change = post - pre;
319→
320→        if change == 0 {
321→            continue;
322→        }
323→
324→        let pre_sol = lamports_to_sol(pre);
325→        let post_sol = lamports_to_sol(post);
326→        let delta_sol = lamports_to_sol(change);
327→
328→        deltas.push(NativeBalanceDelta {
329→            id: Uuid::new_v4(),
330→            raw_transaction_id: raw_tx_id,
331→            network: network.to_string(),
332→            account_address: account.clone(),
333→            native_token: "SOL".to_string(),
334→            pre_balance: pre_sol,
335→            post_balance: post_sol,
336→            delta: delta_sol,
337→            is_fee_payer: idx == 0,
338→            dataset_version_id: None,
339→            created_at: Utc::now(),
340→        });
341→    }
342→
343→    deltas
344→}
