350→/// Extract decoded events (program instructions) from a Solana raw transaction.
351→///
352→/// Extracts top-level and inner instructions from the parsed transaction,
353→/// capturing program_id, instruction data, and account keys. Skips failed
354→/// transactions.
355→pub fn extract_solana_decoded_events(
356→    raw_tx_id: Option<Uuid>,
357→    network: &str,
358→    raw_metadata: &serde_json::Value,
359→) -> Vec<DecodedEvent> {
