361→        match serde_json::from_value(raw_metadata.clone()) {
362→            Ok(tx) => tx,
363→            Err(_) => return vec![],
364→        };
365→
366→    let meta = match &sol_tx.transaction.meta {
367→        Some(m) => m,
368→        None => return vec![],
369→    };
370→
371→    // Skip failed transactions
372→    if meta.err.is_some() {
373→        return vec![];
374→    }
375→
376→    let mut events = Vec::new();
377→    let mut log_index: i32 = 0;
378→
379→    let transaction = &sol_tx.transaction.transaction;
380→    if let solana_transaction_status::EncodedTransaction::Json(ui_tx) = transaction {
381→        if let solana_transaction_status::UiMessage::Parsed(message) = &ui_tx.message {
382→            // Extract top-level instructions
383→            for ix in &message.instructions {
384→                match ix {
385→                    solana_transaction_status::UiInstruction::Parsed(parsed_ix) => {
386→                        let (program_id, decoded_fields, raw_fields) =
