397→                            decoded_fields,
398→                            raw_fields,
399→                            dataset_version_id: None,
400→                            created_at: Utc::now(),
401→                        });
402→                        log_index += 1;
403→                    }
404→                    solana_transaction_status::UiInstruction::Compiled(compiled_ix) => {
405→                        let program_id = message
406→                            .account_keys
407→                            .get(compiled_ix.program_id_index as usize)
408→                            .map(|k| k.pubkey.clone())
409→                            .unwrap_or_else(|| format!("index:{}", compiled_ix.program_id_index));
410→
411→                        let accounts: Vec<String> = compiled_ix
412→                            .accounts
413→                            .iter()
414→                            .map(|&idx| {
415→                                message
416→                                    .account_keys
417→                                    .get(idx as usize)
418→                                    .map(|k| k.pubkey.clone())
419→                                    .unwrap_or_else(|| format!("index:{idx}"))
420→                            })
421→                            .collect();
422→
423→                        let raw_fields = serde_json::json!({
424→                            "data": &compiled_ix.data,
425→                            "accounts": accounts,
426→                        });
427→
428→                        events.push(DecodedEvent {
429→                            id: Uuid::new_v4(),
430→                            raw_transaction_id: raw_tx_id,
431→                            network: network.to_string(),
432→                            program_or_contract: program_id,
433→                            event_signature: None,
434→                            event_name: None,
435→                            log_index,
436→                            decoded_fields: serde_json::json!({}),
437→                            raw_fields,
438→                            dataset_version_id: None,
439→                            created_at: Utc::now(),
440→                        });
441→                        log_index += 1;
442→                    }
443→                }
444→            }
445→        }
446→    }
447→
448→    // Extract inner instructions when available
449→    if let OptionSerializer::Some(inner_instructions) = &meta.inner_instructions {
450→        for inner_group in inner_instructions {
451→            for inner_ix in &inner_group.instructions {
452→                match inner_ix {
453→                    solana_transaction_status::UiInstruction::Parsed(parsed_ix) => {
454→                        let (program_id, decoded_fields, raw_fields) =
455→                            extract_parsed_instruction(parsed_ix);
456→
457→                        events.push(DecodedEvent {
458→                            id: Uuid::new_v4(),
459→                            raw_transaction_id: raw_tx_id,
460→                            network: network.to_string(),
461→                            program_or_contract: program_id,
462→                            event_signature: None,
463→                            event_name: extract_instruction_type(parsed_ix),
464→                            log_index,
465→                            decoded_fields,
466→                            raw_fields,
467→                            dataset_version_id: None,
468→                            created_at: Utc::now(),
469→                        });
470→                        log_index += 1;
471→                    }
472→                    solana_transaction_status::UiInstruction::Compiled(compiled_ix) => {
473→                        let raw_fields = serde_json::json!({
474→                            "data": &compiled_ix.data,
475→                            "accounts": &compiled_ix.accounts,
476→                        });
477→
478→                        events.push(DecodedEvent {
479→                            id: Uuid::new_v4(),
480→                            raw_transaction_id: raw_tx_id,
481→                            network: network.to_string(),
482→                            program_or_contract: format!("index:{}", compiled_ix.program_id_index),
483→                            event_signature: None,
484→                            event_name: None,
485→                            log_index,
486→                            decoded_fields: serde_json::json!({}),
487→                            raw_fields,
488→                            dataset_version_id: None,
489→                            created_at: Utc::now(),
490→                        });
491→                        log_index += 1;
492→                    }
493→                }
494→            }
495→        }
496→    }
497→
498→    events
499→}
