501→/// Extract fields from a parsed Solana instruction.
502→fn extract_parsed_instruction(
503→    ix: &solana_transaction_status::UiParsedInstruction,
504→) -> (String, serde_json::Value, serde_json::Value) {
505→    match ix {
506→        solana_transaction_status::UiParsedInstruction::Parsed(parsed) => {
507→            let program_id = parsed.program_id.clone();
508→            let decoded_fields = parsed.parsed.clone();
509→            let raw_fields = serde_json::json!({
510→                "program": &parsed.program,
511→                "programId": &parsed.program_id,
512→            });
513→            (program_id, decoded_fields, raw_fields)
514→        }
515→        solana_transaction_status::UiParsedInstruction::PartiallyDecoded(partial) => {
516→            let program_id = partial.program_id.clone();
517→            let accounts: Vec<String> = partial.accounts.iter().map(|a| a.to_string()).collect();
518→            let raw_fields = serde_json::json!({
519→                "data": &partial.data,
520→                "accounts": accounts,
521→            });
522→            (program_id, serde_json::json!({}), raw_fields)
523→        }
524→    }
525→}
526→
527→/// Extract instruction type name from a parsed instruction (if available).
528→fn extract_instruction_type(ix: &solana_transaction_status::UiParsedInstruction) -> Option<String> {
529→    match ix {
530→        solana_transaction_status::UiParsedInstruction::Parsed(parsed) => parsed
531→            .parsed
532→            .get("type")
533→            .and_then(|t| t.as_str())
534→            .map(|s| s.to_string()),
535→        solana_transaction_status::UiParsedInstruction::PartiallyDecoded(_) => None,
536→    }
537→}
