536→// ---------------------------------------------------------------------------
537→
538→/// Extract a normalized Hyperliquid position change from raw transaction metadata.
539→///
540→/// Position changes are derived from fills (and liquidations). Each fill that
541→/// opens, increases, or closes a position produces a position change record.
542→pub fn extract_hl_position_changes(
543→    raw_tx_id: Option<Uuid>,
544→    network: &str,
545→    raw_metadata: &serde_json::Value,
546→) -> Vec<HlPositionChange> {
547→    let entry_type = raw_metadata["type"].as_str().unwrap_or("unknown");
548→
549→    match entry_type {
550→        "fill" => extract_position_change_from_fill(raw_tx_id, network, raw_metadata),
551→        "ledger_update" => {
552→            extract_position_change_from_liquidation(raw_tx_id, network, raw_metadata)
553→        }
554→        _ => vec![],
555→    }
556→}
557→
558→fn extract_position_change_from_fill(
559→    raw_tx_id: Option<Uuid>,
560→    network: &str,
561→    raw_metadata: &serde_json::Value,
562→) -> Vec<HlPositionChange> {
563→    let data = &raw_metadata["data"];
564→    let fill: HlFill = match serde_json::from_value(data.clone()) {
565→        Ok(f) => f,
566→        Err(_) => return vec![],
567→    };
568→
569→    let size = BigDecimal::from_str(&fill.sz).unwrap_or_default();
570→    let price = BigDecimal::from_str(&fill.px).unwrap_or_default();
571→
572→    // Determine signed size_delta: buy = positive, sell = negative
573→    let size_delta = if fill.side == "B" { size } else { -size };
574→
575→    vec![HlPositionChange {
576→        id: Uuid::new_v4(),
577→        raw_transaction_id: raw_tx_id,
578→        network: network.to_string(),
579→        coin: fill.coin,
580→        side: fill.side,
581→        size_delta,
582→        price,
583→        direction: fill.dir,
584→        source_event: "fill".to_string(),
585→        dataset_version_id: None,
586→        created_at: Utc::now(),
587→    }]
588→}
589→
590→fn extract_position_change_from_liquidation(
591→    raw_tx_id: Option<Uuid>,
592→    network: &str,
593→    raw_metadata: &serde_json::Value,
594→) -> Vec<HlPositionChange> {
595→    let data = &raw_metadata["data"];
596→    let delta = &data["delta"];
597→    let delta_type = delta["type"].as_str().unwrap_or("unknown");
598→
599→    if delta_type != "liquidation" {
600→        return vec![];
601→    }
602→
603→    // Liquidation events may contain leveraged position info
604→    let coin = delta["coin"].as_str().unwrap_or("UNKNOWN");
605→    let size_str = delta["sz"].as_str().unwrap_or("0");
606→    let price_str = delta["px"].as_str().unwrap_or("0");
607→    let side = delta["side"].as_str().unwrap_or("A");
608→
609→    let size = BigDecimal::from_str(size_str).unwrap_or_default();
610→    let price = BigDecimal::from_str(price_str).unwrap_or_default();
611→
612→    if size == BigDecimal::from(0) {
613→        return vec![];
614→    }
615→
616→    // Liquidation closes a position, so size_delta is opposite to position side
617→    let size_delta = if side == "B" { size } else { -size };
618→
619→    vec![HlPositionChange {
620→        id: Uuid::new_v4(),
621→        raw_transaction_id: raw_tx_id,
622→        network: network.to_string(),
623→        coin: coin.to_string(),
624→        side: side.to_string(),
625→        size_delta,
626→        price,
627→        direction: Some("Liquidation".to_string()),
628→        source_event: "liquidation".to_string(),
629→        dataset_version_id: None,
630→        created_at: Utc::now(),
631→    }]
632→}
