332→// ---------------------------------------------------------------------------
333→// Decoded Event extraction (P3-W3)
334→// ---------------------------------------------------------------------------
335→
336→/// ERC-20 Approval event signature: keccak256("Approval(address,address,uint256)")
337→const ERC20_APPROVAL_TOPIC: &str =
338→    "0x8c5be1e5ebec7d5bd14f71427d1e84f3dd0314c0f7b2291e5b200ac8c7c3b925";
339→
340→/// Extract decoded events from an EVM raw transaction's log metadata.
341→///
342→/// Decodes ALL log events, not just ERC-20 Transfer events. For well-known
343→/// events (Transfer, Approval), provides named decoded_fields. For unknown
344→/// events, decoded_fields mirrors raw topic/data structure.
345→pub fn extract_evm_decoded_events(
346→    raw_tx_id: Option<Uuid>,
347→    network: &str,
348→    raw_metadata: &serde_json::Value,
349→) -> Vec<DecodedEvent> {
350→    let mut events = Vec::new();
351→
352→    // Handle single-log format (topics/data/address at top level)
353→    if let Some(topics) = raw_metadata.get("topics").and_then(|t| t.as_array()) {
354→        let address = raw_metadata
355→            .get("address")
356→            .and_then(|a| a.as_str())
357→            .unwrap_or("unknown")
358→            .to_string();
359→
360→        let data_hex = raw_metadata
361→            .get("data")
362→            .and_then(|d| d.as_str())
363→            .unwrap_or("0x");
364→
365→        let log_index = raw_metadata
366→            .get("logIndex")
367→            .or_else(|| raw_metadata.get("log_index"))
368→            .and_then(|v| v.as_i64().or_else(|| v.as_str().and_then(hex_to_i64_opt)))
369→            .unwrap_or(0) as i32;
370→
371→        let topic0 = topics.first().and_then(|t| t.as_str());
372→
373→        let (event_name, decoded_fields) = decode_evm_event_fields(topic0, topics, data_hex);
374→
375→        let raw_fields = serde_json::json!({
376→            "topics": topics,
377→            "data": data_hex,
378→        });
379→
380→        events.push(DecodedEvent {
381→            id: Uuid::new_v4(),
382→            raw_transaction_id: raw_tx_id,
383→            network: network.to_string(),
384→            program_or_contract: address,
385→            event_signature: topic0.map(|s| s.to_string()),
386→            event_name,
387→            log_index,
388→            decoded_fields,
389→            raw_fields,
390→            dataset_version_id: None,
391→            created_at: Utc::now(),
392→        });
393→    }
394→
395→    // Handle multi-log format (logs array)
396→    if let Some(logs) = raw_metadata.get("logs").and_then(|l| l.as_array()) {
397→        for (idx, log) in logs.iter().enumerate() {
398→            let topics = match log.get("topics").and_then(|t| t.as_array()) {
399→                Some(t) => t,
400→                None => continue,
401→            };
402→
403→            let address = log
404→                .get("address")
405→                .and_then(|a| a.as_str())
406→                .unwrap_or("unknown")
407→                .to_string();
408→
409→            let data_hex = log.get("data").and_then(|d| d.as_str()).unwrap_or("0x");
410→
411→            let log_index = log
412→                .get("logIndex")
413→                .or_else(|| log.get("log_index"))
414→                .and_then(|v| v.as_i64().or_else(|| v.as_str().and_then(hex_to_i64_opt)))
415→                .unwrap_or(idx as i64) as i32;
416→
417→            let topic0 = topics.first().and_then(|t| t.as_str());
418→
419→            let (event_name, decoded_fields) = decode_evm_event_fields(topic0, topics, data_hex);
420→
421→            let raw_fields = serde_json::json!({
422→                "topics": topics,
423→                "data": data_hex,
424→            });
425→
426→            events.push(DecodedEvent {
427→                id: Uuid::new_v4(),
428→                raw_transaction_id: raw_tx_id,
429→                network: network.to_string(),
430→                program_or_contract: address,
431→                event_signature: topic0.map(|s| s.to_string()),
432→                event_name,
433→                log_index,
434→                decoded_fields,
435→                raw_fields,
436→                dataset_version_id: None,
437→                created_at: Utc::now(),
438→            });
439→        }
440→    }
441→
442→    events
443→}
444→
445→/// Decode known EVM event fields by event signature.
446→/// Returns (event_name, decoded_fields).
447→fn decode_evm_event_fields(
448→    topic0: Option<&str>,
449→    topics: &[serde_json::Value],
450→    data_hex: &str,
451→) -> (Option<String>, serde_json::Value) {
452→    match topic0 {
453→        Some(t) if t == ERC20_TRANSFER_TOPIC && topics.len() >= 3 => {
454→            let from = topic_to_address(topics[1].as_str().unwrap_or_default());
455→            let to = topic_to_address(topics[2].as_str().unwrap_or_default());
456→            let value = hex_to_bigdecimal(data_hex).to_string();
457→            (
458→                Some("Transfer".to_string()),
459→                serde_json::json!({
460→                    "from": from,
461→                    "to": to,
462→                    "value": value,
463→                }),
464→            )
465→        }
466→        Some(t) if t == ERC20_APPROVAL_TOPIC && topics.len() >= 3 => {
467→            let owner = topic_to_address(topics[1].as_str().unwrap_or_default());
468→            let spender = topic_to_address(topics[2].as_str().unwrap_or_default());
469→            let value = hex_to_bigdecimal(data_hex).to_string();
470→            (
471→                Some("Approval".to_string()),
472→                serde_json::json!({
473→                    "owner": owner,
474→                    "spender": spender,
475→                    "value": value,
476→                }),
477→            )
478→        }
479→        Some(_) => {
480→            // Unknown event — provide indexed topics and data
481→            let indexed: Vec<String> = topics
482→                .iter()
483→                .skip(1) // skip topic0 (the signature)
484→                .filter_map(|t| t.as_str().map(|s| s.to_string()))
485→                .collect();
486→            (
487→                None,
488→                serde_json::json!({
489→                    "indexed_topics": indexed,
490→                    "data": data_hex,
491→                }),
492→            )
493→        }
494→        None => {
495→            // Anonymous event (no topics)
496→            (
497→                None,
498→                serde_json::json!({
499→                    "data": data_hex,
500→                }),
501→            )
502→        }
503→    }
504→}
505→
506→/// Parse hex string to i64 (for log index fields that may be hex-encoded).
507→fn hex_to_i64_opt(hex: &str) -> Option<i64> {
508→    let stripped = hex.strip_prefix("0x").unwrap_or(hex);
509→    i64::from_str_radix(stripped, 16).ok()
510→}
